/**
 * 英语词汇库
 * - 高中核心词汇（覆盖高考高频词，按主题分组）
 * - 大学英语四级（CET4）核心词汇（按主题分组）
 * 核心高频词含：音标、词性、释义、例句、例句翻译
 * 大量基础词含：词性、释义（部分含音标）
 * 供课程动态生成单元与课时，以及「单词任务」模式按 20 词一轮学习。
 *
 * 当前词条总数：高中 1810 词 / 四级 1729 词（合计 3539 词）
 */

export interface VocabEntry {
  term: string;
  phonetic?: string; // 音标（高频词提供，部分词可缺省）
  pos?: string; // 词性 n./v./adj./adv./prep. 等
  meaning: string; // 中文释义
  example?: string; // 例句（英文），核心高频词提供
  exampleMeaning?: string; // 例句翻译
}

export interface VocabGroup {
  id: string;
  title: string; // 主题
  level: 'senior' | 'cet4'; // 高中 / 四级
  words: VocabEntry[];
}

